-- Seed detailed public wiki translations.

with translations (translation_key, namespace, description, lv, en) as (
  values
    ('wiki.docs.metadata.title', 'wiki', 'Detailed wiki metadata title', 'Sistēmas wiki', 'System wiki'),
    ('wiki.docs.metadata.description', 'wiki', 'Detailed wiki metadata description', 'Detalizēta Estimate Builder dokumentācija par projektiem, tāmēm, materiālu patēriņu, eksportu un administrēšanu.', 'Detailed Estimate Builder documentation about projects, estimates, material consumption, exports, and administration.'),
    ('wiki.docs.back_to_login', 'wiki', 'Back to login link', 'Atpakaļ uz pieslēgšanos', 'Back to sign in'),
    ('wiki.docs.title', 'wiki', 'Detailed wiki page title', 'Sistēmas wiki', 'System wiki'),
    ('wiki.docs.subtitle', 'wiki', 'Detailed wiki sidebar subtitle', 'Detalizēts ceļvedis par galvenajām sistēmas darbībām un aprēķinu loģiku.', 'A detailed guide to the main system workflows and calculation logic.'),
    ('wiki.docs.nav.label', 'wiki', 'Detailed wiki navigation aria label', 'Wiki sadaļas', 'Wiki sections'),
    ('wiki.docs.nav.overview', 'wiki', 'Detailed wiki overview nav label', 'Kopskats', 'Overview'),
    ('wiki.docs.nav.projects', 'wiki', 'Detailed wiki projects nav label', 'Projekti', 'Projects'),
    ('wiki.docs.nav.modules', 'wiki', 'Detailed wiki modules nav label', 'Ēku moduļi', 'Building modules'),
    ('wiki.docs.nav.estimate_template', 'wiki', 'Detailed wiki estimate template nav label', 'Tāmes sagatave', 'Estimate template'),
    ('wiki.docs.nav.material_consumption', 'wiki', 'Detailed wiki material consumption nav label', 'Materiāla patēriņš', 'Material consumption'),
    ('wiki.docs.nav.price_control', 'wiki', 'Detailed wiki price control nav label', 'Cenas un redzamība', 'Prices and visibility'),
    ('wiki.docs.nav.exports', 'wiki', 'Detailed wiki exports nav label', 'Eksports', 'Exports'),
    ('wiki.docs.nav.admin', 'wiki', 'Detailed wiki admin nav label', 'Administrēšana', 'Administration'),
    ('wiki.docs.overview.eyebrow', 'wiki', 'Detailed wiki overview eyebrow', 'Kopskats', 'Overview'),
    ('wiki.docs.overview.title', 'wiki', 'Detailed wiki overview title', 'Ko sistēmā dara ikdienā?', 'What do you do in the system day to day?'),
    ('wiki.docs.overview.body_1', 'wiki', 'Detailed wiki overview first paragraph', 'Estimate Builder ir darba vide, kur no sagatavēm un kataloga datiem tiek izveidots konkrēta projekta aprēķins. Lietotājs sāk ar projektu, izvēlas vai pielāgo ēkas moduli, pārbauda tāmes pozīcijas un beigās eksportē piedāvājumu.', 'Estimate Builder is a workspace where templates and catalog data become a calculation for a specific project. The user starts with a project, selects or adjusts a building module, reviews estimate positions, and finally exports an offer.'),
    ('wiki.docs.overview.body_2', 'wiki', 'Detailed wiki overview second paragraph', 'Svarīgākā doma: sagatave un katalogs nav tikai tekstu saraksts. Tie nosaka, kā veidojas darba, materiālu un mehānismu izmaksas katrai projekta pozīcijai.', 'The key idea: the template and catalog are not just text lists. They define how labor, material, and mechanism costs are formed for each project position.'),
    ('wiki.docs.projects.eyebrow', 'wiki', 'Detailed wiki projects eyebrow', 'Projekti', 'Projects'),
    ('wiki.docs.projects.title', 'wiki', 'Detailed wiki projects title', 'Projekts ir vieta, kur sagatave kļūst par reālu piedāvājumu', 'A project is where a template becomes a real offer'),
    ('wiki.docs.projects.body', 'wiki', 'Detailed wiki projects body', 'Projektā tiek apvienoti klienta dati, izvēlētais ēkas modulis, projekta tāme un dokumenti, ko vēlāk nodod klientam vai izmanto iekšējai kontrolei.', 'A project combines client details, the selected building module, the project estimate, and the documents later sent to the client or used for internal review.'),
    ('wiki.docs.projects.block_lifecycle.title', 'wiki', 'Detailed wiki project lifecycle block title', 'Projekta dzīves cikls', 'Project lifecycle'),
    ('wiki.docs.projects.lifecycle.item_1', 'wiki', 'Detailed wiki project lifecycle first item', 'Aktīvie projekti redzami galvenajā projektu sarakstā.', 'Active projects are shown in the main project list.'),
    ('wiki.docs.projects.lifecycle.item_2', 'wiki', 'Detailed wiki project lifecycle second item', 'Pabeigtus projektus var pārcelt arhīvā, lai netraucētu ikdienas darbam.', 'Completed projects can be moved to the archive so they do not distract from daily work.'),
    ('wiki.docs.projects.lifecycle.item_3', 'wiki', 'Detailed wiki project lifecycle third item', 'Projektā glabā klienta kontaktus, projekta statusu un piesaistīto ēkas moduli.', 'The project stores client contacts, project status, and the linked building module.'),
    ('wiki.docs.projects.block_team.title', 'wiki', 'Detailed wiki project team block title', 'Komandas pieeja', 'Team access'),
    ('wiki.docs.projects.team.item_1', 'wiki', 'Detailed wiki project team first item', 'Uzņēmuma lietotāji strādā ar tiem datiem, kam viņiem ir piešķirta pieeja.', 'Company users work with the data they have been granted access to.'),
    ('wiki.docs.projects.team.item_2', 'wiki', 'Detailed wiki project team second item', 'Administrators var mainīt lietotāju grupas un darbību tiesības.', 'An administrator can change user groups and action permissions.'),
    ('wiki.docs.projects.team.item_3', 'wiki', 'Detailed wiki project team third item', 'Sistēmas administrators redz uzņēmumu un lietotāju pārvaldības sadaļas.', 'The system administrator can access company and user management sections.'),
    ('wiki.docs.modules.eyebrow', 'wiki', 'Detailed wiki modules eyebrow', 'Ēku moduļi', 'Building modules'),
    ('wiki.docs.modules.title', 'wiki', 'Detailed wiki modules title', 'Modulis apraksta ēkas tipu, aprakstu un apjomu avotus', 'A module describes the building type, description, and quantity sources'),
    ('wiki.docs.modules.body_1', 'wiki', 'Detailed wiki modules first paragraph', 'Ēku modulis satur apraksta blokus, vizuālos materiālus, izmēru variantus un aprēķinos izmantojamos apjomus. Ja pozīcija ir piesaistīta moduļa lielumam, tās daudzums projektā nāk no šī moduļa datiem.', 'A building module contains description blocks, visual materials, size variants, and quantities used in calculations. If a position is linked to a module size, its quantity in the project comes from that module data.'),
    ('wiki.docs.modules.body_2', 'wiki', 'Detailed wiki modules second paragraph', 'Piemēram, ja modulī ir aprēķināta sienu platība, tāmes pozīciju var piesaistīt šai platībai. Tad projektā nav katru reizi manuāli jāpārraksta daudzums.', 'For example, if the module calculates wall area, an estimate position can be linked to that area. Then the quantity does not need to be retyped manually in each project.'),
    ('wiki.docs.estimate.eyebrow', 'wiki', 'Detailed wiki estimate eyebrow', 'Tāmes sagatave', 'Estimate template'),
    ('wiki.docs.estimate.title', 'wiki', 'Detailed wiki estimate title', 'Sagatave nosaka pozīcijas, aprēķinu un piedāvājuma struktūru', 'The template defines positions, calculation, and offer structure'),
    ('wiki.docs.estimate.body', 'wiki', 'Detailed wiki estimate body', 'Tāmes sagatavi izmanto kā atkārtotu bāzi. Tajā definē sadaļas, pozīcijas, materiālus, mehānismus, laika normas un redzamību piedāvājumā.', 'The estimate template is used as a reusable base. It defines sections, positions, materials, mechanisms, time norms, and offer visibility.'),
    ('wiki.docs.estimate.block_structure.title', 'wiki', 'Detailed wiki estimate structure block title', 'Struktūra', 'Structure'),
    ('wiki.docs.estimate.structure.item_1', 'wiki', 'Detailed wiki estimate structure first item', 'Tāme sastāv no kategorijām, apakškategorijām un pozīcijām.', 'An estimate consists of categories, subcategories, and positions.'),
    ('wiki.docs.estimate.structure.item_2', 'wiki', 'Detailed wiki estimate structure second item', 'Pozīcijas var pārkārtot un pārvietot starp sadaļām.', 'Positions can be reordered and moved between sections.'),
    ('wiki.docs.estimate.structure.item_3', 'wiki', 'Detailed wiki estimate structure third item', 'Sagatave kalpo kā bāze jauniem projektiem, bet projektā to var pielāgot konkrētajam piedāvājumam.', 'The template acts as the base for new projects, but it can be adjusted in the project for the specific offer.'),
    ('wiki.docs.estimate.block_position.title', 'wiki', 'Detailed wiki estimate position block title', 'Pozīcijas saturs', 'Position contents'),
    ('wiki.docs.estimate.position.item_1', 'wiki', 'Detailed wiki estimate position first item', 'Pozīcijai norāda nosaukumu, laika normu, materiālus un mehānismus.', 'A position has a name, time norm, materials, and mechanisms.'),
    ('wiki.docs.estimate.position.item_2', 'wiki', 'Detailed wiki estimate position second item', 'Darba izmaksas rodas no laika normas un uzņēmuma vai pozīcijas stundas likmes.', 'Labor costs come from the time norm and the company or position hourly rate.'),
    ('wiki.docs.estimate.position.item_3', 'wiki', 'Detailed wiki estimate position third item', 'Materiālu un mehānismu cenas nāk no pozīciju kataloga.', 'Material and mechanism prices come from the position catalog.'),
    ('wiki.docs.material.eyebrow', 'wiki', 'Detailed wiki material consumption eyebrow', 'Materiāla patēriņš', 'Material consumption'),
    ('wiki.docs.material.title', 'wiki', 'Detailed wiki material consumption title', 'Ja pozīcijas mērvienība atšķiras no materiāla mērvienības', 'When the position unit differs from the material unit'),
    ('wiki.docs.material.body_1', 'wiki', 'Detailed wiki material consumption first paragraph', 'Šī ir situācija, kad galvenā tāmes pozīcija tiek rēķināta vienā mērvienībā, bet tai piesaistītais materiāls katalogā ir citā mērvienībā. Piemēram, pozīcija ir m², bet materiāls ir m.', 'This is the case where the main estimate position is calculated in one unit, but the linked catalog material uses another unit. For example, the position is m², while the material is m.'),
    ('wiki.docs.material.body_2', 'wiki', 'Detailed wiki material consumption second paragraph', 'Sistēmā šo starpību risina ar lauku “Patēriņš”. Tas nozīmē: cik materiāla mērvienību vajag uz vienu pozīcijas mērvienību.', 'The system handles this difference with the “Consumption” field. It means: how many material units are needed for one position unit.'),
    ('wiki.docs.material.formula.title', 'wiki', 'Detailed wiki material formula title', 'Formula', 'Formula'),
    ('wiki.docs.material.formula.body', 'wiki', 'Detailed wiki material formula body', 'materiāla vienības cena × patēriņš = materiāla izmaksas uz 1 pozīcijas vienību', 'material unit price × consumption = material cost per 1 position unit'),
    ('wiki.docs.material.steps.title', 'wiki', 'Detailed wiki material steps title', 'Kā to ievadīt', 'How to enter it'),
    ('wiki.docs.material.steps.item_1', 'wiki', 'Detailed wiki material first step', 'Atver tāmes sagatavi vai konkrētā projekta tāmi un labo vajadzīgo pozīciju.', 'Open the estimate template or the specific project estimate and edit the needed position.'),
    ('wiki.docs.material.steps.item_2', 'wiki', 'Detailed wiki material second step', 'Pozīcijas modālī sadaļā “Materiāli” pievieno materiālu no kataloga.', 'In the position modal, add a material from the catalog in the “Materials” section.'),
    ('wiki.docs.material.steps.item_3', 'wiki', 'Detailed wiki material third step', 'Ja materiāla mērvienība atšķiras no pozīcijas mērvienības, blakus materiālam parādās patēriņa lauks.', 'If the material unit differs from the position unit, a consumption field appears next to the material.'),
    ('wiki.docs.material.steps.item_4', 'wiki', 'Detailed wiki material fourth step', 'Ievadi, cik materiāla vienību vajag uz vienu pozīcijas mērvienību.', 'Enter how many material units are needed for one position unit.'),
    ('wiki.docs.material.steps.item_5', 'wiki', 'Detailed wiki material fifth step', 'Saglabā pozīciju; sistēma pārrēķina materiāla izmaksu vienības cenā.', 'Save the position; the system recalculates the material cost in the unit price.'),
    ('wiki.docs.material.example.title', 'wiki', 'Detailed wiki material example title', 'Piemērs', 'Example'),
    ('wiki.docs.material.example.body_1', 'wiki', 'Detailed wiki material example first paragraph', 'Pozīcija: “Sienas apdare”, mērvienība m². Materiāls: “Līste”, mērvienība m, cena 2.50 EUR/m. Uz vienu m² vajag 1.8 m līstes.', 'Position: “Wall finishing”, unit m². Material: “Trim”, unit m, price 2.50 EUR/m. One m² requires 1.8 m of trim.'),
    ('wiki.docs.material.example.body_2', 'wiki', 'Detailed wiki material example second paragraph', 'Patēriņa laukā ievada 1.8. Sistēma aprēķina 2.50 × 1.8 = 4.50 EUR/m². Ja projekta apjoms ir 25 m², materiāla kopsumma ir 25 × 4.50 = 112.50 EUR.', 'Enter 1.8 in the consumption field. The system calculates 2.50 × 1.8 = 4.50 EUR/m². If the project quantity is 25 m², the material total is 25 × 4.50 = 112.50 EUR.'),
    ('wiki.docs.material.note.title', 'wiki', 'Detailed wiki material note title', 'Svarīgi', 'Important'),
    ('wiki.docs.material.note.body', 'wiki', 'Detailed wiki material note body', 'Ja materiāla mērvienība sakrīt ar pozīcijas mērvienību, patēriņa lauks netiek rādīts un sistēma izmanto patēriņu 1.', 'If the material unit matches the position unit, the consumption field is not shown and the system uses consumption 1.'),
    ('wiki.docs.price.eyebrow', 'wiki', 'Detailed wiki price eyebrow', 'Cenas un redzamība', 'Prices and visibility'),
    ('wiki.docs.price.title', 'wiki', 'Detailed wiki price title', 'Iekšējais aprēķins un klienta piedāvājums nav viens un tas pats skats', 'The internal calculation and client offer are not the same view'),
    ('wiki.docs.price.body', 'wiki', 'Detailed wiki price body', 'Sistēma ļauj uzturēt detalizētu iekšējo aprēķinu, bet piedāvājumā rādīt tikai to informāciju, kas klientam ir vajadzīga.', 'The system lets you maintain a detailed internal calculation while showing only the information the client needs in the offer.'),
    ('wiki.docs.price.block_catalog.title', 'wiki', 'Detailed wiki price catalog block title', 'Kataloga cenas', 'Catalog prices'),
    ('wiki.docs.price.catalog.item_1', 'wiki', 'Detailed wiki price catalog first item', 'Pozīciju katalogā uztur materiālu, darbu un mehānismu vienības cenas.', 'The position catalog stores unit prices for materials, labor, and mechanisms.'),
    ('wiki.docs.price.catalog.item_2', 'wiki', 'Detailed wiki price catalog second item', 'Cenu vēsture palīdz redzēt, kad cena mainīta un no kādas vērtības.', 'Price history shows when a price changed and from what value.'),
    ('wiki.docs.price.catalog.item_3', 'wiki', 'Detailed wiki price catalog third item', 'Ja katalogā cena mainās, projektā var redzēt, kur pozīcijas kļuvušas novecojušas.', 'If a catalog price changes, the project can show which positions became outdated.'),
    ('wiki.docs.price.block_visibility.title', 'wiki', 'Detailed wiki price visibility block title', 'Redzamība piedāvājumā', 'Offer visibility'),
    ('wiki.docs.price.visibility.item_1', 'wiki', 'Detailed wiki price visibility first item', 'Apakškategoriju var paslēpt no piedāvājuma, ja tā vajadzīga tikai iekšējam aprēķinam.', 'A subcategory can be hidden from the offer if it is needed only for internal calculation.'),
    ('wiki.docs.price.visibility.item_2', 'wiki', 'Detailed wiki price visibility second item', 'Var paslēpt arī cenu detalizāciju, atstājot piedāvājumā tikai kopsummu.', 'Price detail can also be hidden while leaving only the total in the offer.'),
    ('wiki.docs.price.visibility.item_3', 'wiki', 'Detailed wiki price visibility third item', 'Šīs izvēles ļauj no vienas tāmes sagatavot gan iekšējo aprēķinu, gan klienta dokumentu.', 'These choices let one estimate support both internal calculation and the client document.'),
    ('wiki.docs.exports.eyebrow', 'wiki', 'Detailed wiki exports eyebrow', 'Eksports', 'Exports'),
    ('wiki.docs.exports.title', 'wiki', 'Detailed wiki exports title', 'No projekta var izveidot dokumentus', 'Documents can be created from a project'),
    ('wiki.docs.exports.item_1', 'wiki', 'Detailed wiki exports first item', 'PDF piedāvājums klientam ar uzņēmuma datiem, piedāvājuma saturu un derīguma termiņu.', 'A PDF offer for the client with company details, offer content, and validity period.'),
    ('wiki.docs.exports.item_2', 'wiki', 'Detailed wiki exports second item', 'Excel tāme iekšējai pārbaudei, korekcijām un detalizētai aprēķinu kontrolei.', 'An Excel estimate for internal review, adjustments, and detailed calculation control.'),
    ('wiki.docs.exports.item_3', 'wiki', 'Detailed wiki exports third item', 'Eksporta failu nosaukumi tiek sagatavoti atbilstoši izvēlētajai valodai.', 'Export filenames are prepared according to the selected language.'),
    ('wiki.docs.admin.eyebrow', 'wiki', 'Detailed wiki admin eyebrow', 'Administrēšana', 'Administration'),
    ('wiki.docs.admin.title', 'wiki', 'Detailed wiki admin title', 'Administrēšana uztur sistēmas pamata datus', 'Administration maintains the system base data'),
    ('wiki.docs.admin.item_1', 'wiki', 'Detailed wiki admin first item', 'Sistēmas administrators pārvalda uzņēmumus un uzņēmumu lietotājus.', 'The system administrator manages companies and company users.'),
    ('wiki.docs.admin.item_2', 'wiki', 'Detailed wiki admin second item', 'Valodu sadaļā uztur aktīvās sistēmas valodas un noklusējuma valodu.', 'The languages section maintains active system languages and the default language.'),
    ('wiki.docs.admin.item_3', 'wiki', 'Detailed wiki admin third item', 'Tulkojumu sadaļā vienai atslēgai var rediģēt tekstus visām sistēmas valodām.', 'The translations section lets one key be edited for all system languages.'),
    ('wiki.docs.admin.item_4', 'wiki', 'Detailed wiki admin fourth item', 'Grupu sadaļā tiek pārvaldītas navigācijas un darbību tiesības.', 'The groups section manages navigation and action permissions.')
)
insert into public.site_translations (translation_key, namespace, description, values)
select
  translation_key,
  namespace,
  description,
  jsonb_build_object('lv', lv, 'en', en)
from translations
on conflict (translation_key) do update
set
  namespace = excluded.namespace,
  description = excluded.description,
  values = public.site_translations.values || excluded.values,
  updated_at = now();
